//! The Windows backend, as the SandboxScope's Windows says: AppContainer.
//!
//! Each run gets an AppContainer of its own, `Suspense.<profile>.<run id>`,
//! made before it starts and deleted after. The filesystem boundary is the
//! access lists: each path the policy grants is given an access entry for
//! that AppContainer's SID alone, read and execute or modify, recorded first
//! in a ledger so it is always removed again, after the run or at the next
//! launch. The harness is started by the application's own program run as
//! `suspense --sandbox-launch <spec> -- <program>…`, which makes the
//! AppContainer and the grants, starts the harness suspended in it with only
//! the `internetClient` capability and its standard handles, puts it in a
//! job object that ends everything with it and forbids breaking away, and
//! only then resumes it.
//!
//! This backend has not run on Windows yet: it type-checks against the
//! Windows target, and is "in theory" until its tests pass on a Windows
//! runner, as SANDBOX.md says.

use std::ffi::OsStr;
use std::os::windows::ffi::OsStrExt as _;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde::{Deserialize, Serialize};
use windows_sys::Win32::Foundation::{
    CloseHandle, GetLastError, HANDLE, HANDLE_FLAG_INHERIT, INVALID_HANDLE_VALUE, LocalFree,
    SetHandleInformation,
};
use windows_sys::Win32::Security::Authorization::{
    ConvertSidToStringSidW, ConvertStringSecurityDescriptorToSecurityDescriptorW, EXPLICIT_ACCESS_W,
    GRANT_ACCESS, GetNamedSecurityInfoW, REVOKE_ACCESS, SDDL_REVISION_1, SE_FILE_OBJECT,
    SetEntriesInAclW, SetNamedSecurityInfoW, TRUSTEE_IS_SID, TRUSTEE_IS_UNKNOWN, TRUSTEE_W,
};
use windows_sys::Win32::Security::Isolation::{
    CreateAppContainerProfile, DeleteAppContainerProfile, DeriveAppContainerSidFromAppContainerName,
};
use windows_sys::Win32::Security::{
    ACL, CreateWellKnownSid, DACL_SECURITY_INFORMATION, FreeSid, GetTokenInformation,
    NO_INHERITANCE, PSECURITY_DESCRIPTOR, PSID, SECURITY_ATTRIBUTES, SECURITY_CAPABILITIES,
    SE_GROUP_ENABLED, SID_AND_ATTRIBUTES, SUB_CONTAINERS_AND_OBJECTS_INHERIT, TOKEN_QUERY,
    TOKEN_USER, TokenUser, WinCapabilityInternetClientSid,
};
use windows_sys::Win32::Storage::FileSystem::{
    DELETE, FILE_ATTRIBUTE_REPARSE_POINT, FILE_GENERIC_EXECUTE, FILE_GENERIC_READ,
    FILE_GENERIC_WRITE, GetFileAttributesW, INVALID_FILE_ATTRIBUTES, PIPE_ACCESS_DUPLEX,
};
use windows_sys::Win32::System::Console::{
    GetStdHandle, STD_ERROR_HANDLE, STD_INPUT_HANDLE, STD_OUTPUT_HANDLE,
};
use windows_sys::Win32::System::JobObjects::{
    AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
    JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JobObjectExtendedLimitInformation, SetInformationJobObject,
};
use windows_sys::Win32::System::Pipes::{
    ConnectNamedPipe, CreateNamedPipeW, PIPE_READMODE_BYTE, PIPE_REJECT_REMOTE_CLIENTS,
    PIPE_TYPE_BYTE, PIPE_UNLIMITED_INSTANCES, PIPE_WAIT,
};
use windows_sys::Win32::System::Registry::{HKEY_LOCAL_MACHINE, RRF_RT_REG_SZ, RegGetValueW};
use windows_sys::Win32::System::Threading::{
    CREATE_NO_WINDOW, CREATE_SUSPENDED, CREATE_UNICODE_ENVIRONMENT, CreateProcessW,
    DeleteProcThreadAttributeList, EXTENDED_STARTUPINFO_PRESENT, GetCurrentProcess,
    GetExitCodeProcess, INFINITE, InitializeProcThreadAttributeList, LPPROC_THREAD_ATTRIBUTE_LIST,
    OpenProcessToken, PROC_THREAD_ATTRIBUTE_HANDLE_LIST, PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES,
    PROCESS_INFORMATION, ResumeThread, STARTF_USESTDHANDLES, STARTUPINFOEXW, UpdateProcThreadAttribute,
    WaitForSingleObject,
};

use super::{Access, Compiled, Refused};

/// The argument the application is run with to launch a sandboxed run.
pub const LAUNCH_ARG: &str = "--sandbox-launch";

/// The first Windows build with what AppContainer sandboxing needs: 1809.
const LEAST_BUILD: u32 = 17763;

/// `HRESULT_FROM_WIN32(ERROR_ALREADY_EXISTS)`.
const ALREADY_EXISTS: i32 = 0x800700B7_u32 as i32;

fn wide(text: impl AsRef<OsStr>) -> Vec<u16> {
    text.as_ref().encode_wide().chain(std::iter::once(0)).collect()
}

fn failed(message: impl Into<String>) -> Refused {
    Refused {
        message: message.into(),
        details: format!("Windows error {}", unsafe { GetLastError() }),
    }
}

/// The Windows build number, as the registry holds it.
fn build() -> Option<u32> {
    let key = wide("SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion");
    let value = wide("CurrentBuildNumber");
    let mut buffer = [0u16; 32];
    let mut size = (buffer.len() * 2) as u32;
    let result = unsafe {
        RegGetValueW(
            HKEY_LOCAL_MACHINE,
            key.as_ptr(),
            value.as_ptr(),
            RRF_RT_REG_SZ,
            std::ptr::null_mut(),
            buffer.as_mut_ptr().cast(),
            &mut size,
        )
    };
    if result != 0 {
        return None;
    }
    let text = String::from_utf16_lossy(&buffer[..(size as usize / 2).saturating_sub(1)]);
    text.trim().parse().ok()
}

pub fn status() -> Result<String, Refused> {
    match build() {
        Some(build) if build >= LEAST_BUILD => Ok("AppContainer: files and named pipes".into()),
        Some(build) => Err(Refused {
            message: format!(
                "this Windows is build {build}, and the sandbox needs Windows 10 version 1809 \
                 (build {LEAST_BUILD}) or later"
            ),
            details: String::new(),
        }),
        None => Err(Refused {
            message: "this Windows's version couldn't be read, so the sandbox can't tell it can run"
                .into(),
            details: String::new(),
        }),
    }
}

/// The AppContainer SID of `name`, as a string; none where it can't be
/// derived.
pub fn container_sid(name: &str) -> Option<String> {
    let name = wide(name);
    let mut sid: PSID = std::ptr::null_mut();
    if unsafe { DeriveAppContainerSidFromAppContainerName(name.as_ptr(), &mut sid) } < 0 {
        return None;
    }
    let text = sid_string(sid);
    unsafe { FreeSid(sid) };
    text
}

fn sid_string(sid: PSID) -> Option<String> {
    let mut text = std::ptr::null_mut();
    if unsafe { ConvertSidToStringSidW(sid, &mut text) } == 0 {
        return None;
    }
    let length = (0..).take_while(|&i| unsafe { *text.add(i) } != 0).count();
    let string = String::from_utf16_lossy(unsafe { std::slice::from_raw_parts(text, length) });
    unsafe { LocalFree(text.cast()) };
    Some(string)
}

/// The signed-in user's SID, as a string.
pub fn user_sid() -> Option<String> {
    let mut token: HANDLE = std::ptr::null_mut();
    if unsafe { OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token) } == 0 {
        return None;
    }
    let mut buffer = vec![0u8; 256];
    let mut length = 0u32;
    let ok = unsafe {
        GetTokenInformation(
            token,
            TokenUser,
            buffer.as_mut_ptr().cast(),
            buffer.len() as u32,
            &mut length,
        )
    };
    unsafe { CloseHandle(token) };
    if ok == 0 {
        return None;
    }
    let user = unsafe { &*(buffer.as_ptr() as *const TOKEN_USER) };
    sid_string(user.User.Sid)
}

/// What the launcher is given: the run's AppContainer, what to grant, and
/// the ledger to record each grant in first.
#[derive(Debug, Serialize, Deserialize)]
struct LaunchSpec {
    container: String,
    grants: Vec<(PathBuf, bool)>,
    ledger: PathBuf,
}

/// One grant recorded in a ledger: its path and the SID it was made to.
#[derive(Debug, Serialize, Deserialize)]
struct Granted {
    path: PathBuf,
    sid: String,
}

/// Where the ledgers are kept: Suspense's data directory.
fn ledgers() -> PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(std::env::temp_dir)
        .join("suspense")
        .join("sandbox-ledger")
}

fn ledger(container: &str) -> PathBuf {
    ledgers().join(format!("{container}.jsonl"))
}

/// Puts the sandbox on `command`: started through the launcher, which makes
/// the run's AppContainer and grants before the harness runs in it.
pub fn enforce(command: &mut Command, compiled: &Compiled) -> Result<(), Refused> {
    status()?;
    if compiled.label.is_empty() {
        return Err(Refused {
            message: "the run has no AppContainer named for it".into(),
            details: String::new(),
        });
    }
    let spec = LaunchSpec {
        container: compiled.label.clone(),
        grants: compiled
            .rules
            .iter()
            .map(|rule| (rule.path.clone(), rule.access == Access::ReadWrite))
            .collect(),
        ledger: ledger(&compiled.label),
    };
    let file = std::env::temp_dir().join(format!("{}.launch.json", compiled.label));
    let text = serde_json::to_string(&spec).map_err(|err| Refused {
        message: "the run's launch couldn't be written".into(),
        details: err.to_string(),
    })?;
    std::fs::write(&file, text).map_err(|err| Refused {
        message: "the run's launch couldn't be written".into(),
        details: err.to_string(),
    })?;
    let exe = std::env::current_exe().map_err(|err| Refused {
        message: "the application couldn't find itself to launch the run".into(),
        details: err.to_string(),
    })?;
    let program = command.get_program().to_owned();
    let args: Vec<std::ffi::OsString> = command.get_args().map(ToOwned::to_owned).collect();
    let envs: Vec<(std::ffi::OsString, Option<std::ffi::OsString>)> = command
        .get_envs()
        .map(|(key, value)| (key.to_owned(), value.map(ToOwned::to_owned)))
        .collect();
    let dir = command.get_current_dir().map(ToOwned::to_owned);
    let mut wrapped = crate::process::command(exe);
    wrapped.arg(LAUNCH_ARG).arg(&file).arg("--").arg(program).args(args);
    for (key, value) in envs {
        match value {
            Some(value) => wrapped.env(key, value),
            None => wrapped.env_remove(key),
        };
    }
    if let Some(dir) = dir {
        wrapped.current_dir(dir);
    }
    *command = wrapped;
    Ok(())
}

/// Gives `sid` `access` to `path`, or with none, takes away what it was
/// given, the change carried down to everything beneath it.
fn set_access(path: &Path, sid: &str, access: Option<bool>) -> Result<(), Refused> {
    let name = wide(path);
    // Never through a link: a reparse point is granted as nothing.
    let attributes = unsafe { GetFileAttributesW(name.as_ptr()) };
    if attributes == INVALID_FILE_ATTRIBUTES {
        return Ok(());
    }
    if access.is_some() && attributes & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
        return Err(Refused {
            message: format!("{} is a link, which is never granted", path.display()),
            details: String::new(),
        });
    }
    let folder = attributes & windows_sys::Win32::Storage::FileSystem::FILE_ATTRIBUTE_DIRECTORY != 0;
    let mut sid_value: PSID = std::ptr::null_mut();
    let sid_text = wide(sid);
    if unsafe {
        windows_sys::Win32::Security::Authorization::ConvertStringSidToSidW(sid_text.as_ptr(), &mut sid_value)
    } == 0
    {
        return Err(failed(format!("the run's identity couldn't be read to grant {}", path.display())));
    }
    let mut old: *mut ACL = std::ptr::null_mut();
    let mut descriptor: PSECURITY_DESCRIPTOR = std::ptr::null_mut();
    let read = unsafe {
        GetNamedSecurityInfoW(
            name.as_ptr(),
            SE_FILE_OBJECT,
            DACL_SECURITY_INFORMATION,
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            &mut old,
            std::ptr::null_mut(),
            &mut descriptor,
        )
    };
    if read != 0 {
        unsafe { LocalFree(sid_value) };
        return Err(Refused {
            message: format!("the access list of {} couldn't be read", path.display()),
            details: format!("Windows error {read}"),
        });
    }
    let permissions = match access {
        Some(true) => FILE_GENERIC_READ | FILE_GENERIC_WRITE | FILE_GENERIC_EXECUTE | DELETE,
        _ => FILE_GENERIC_READ | FILE_GENERIC_EXECUTE,
    };
    let entry = EXPLICIT_ACCESS_W {
        grfAccessPermissions: permissions,
        grfAccessMode: if access.is_some() { GRANT_ACCESS } else { REVOKE_ACCESS },
        grfInheritance: if folder { SUB_CONTAINERS_AND_OBJECTS_INHERIT } else { NO_INHERITANCE },
        Trustee: TRUSTEE_W {
            pMultipleTrustee: std::ptr::null_mut(),
            MultipleTrusteeOperation: 0,
            TrusteeForm: TRUSTEE_IS_SID,
            TrusteeType: TRUSTEE_IS_UNKNOWN,
            ptstrName: sid_value.cast(),
        },
    };
    let mut new: *mut ACL = std::ptr::null_mut();
    let merged = unsafe { SetEntriesInAclW(1, &entry, old, &mut new) };
    let result = if merged != 0 {
        Err(Refused {
            message: format!("the access list of {} couldn't be changed", path.display()),
            details: format!("Windows error {merged}"),
        })
    } else {
        // By name, so the change is carried down to what it holds.
        let set = unsafe {
            SetNamedSecurityInfoW(
                name.as_ptr(),
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                new,
                std::ptr::null(),
            )
        };
        if set != 0 {
            Err(Refused {
                message: format!(
                    "{} couldn't be granted: its access list can't be changed by you",
                    path.display()
                ),
                details: format!("Windows error {set}"),
            })
        } else {
            Ok(())
        }
    };
    unsafe {
        if !new.is_null() {
            LocalFree(new.cast());
        }
        LocalFree(descriptor);
        LocalFree(sid_value);
    }
    result
}

/// Removes every grant the ledger of `container` records, and the
/// AppContainer itself, then the ledger: after a run, however it ended.
pub fn cleanup(container: &str) {
    let file = ledger(container);
    if let Ok(text) = std::fs::read_to_string(&file) {
        for line in text.lines() {
            if let Ok(granted) = serde_json::from_str::<Granted>(line) {
                set_access(&granted.path, &granted.sid, None).ok();
            }
        }
    }
    let name = wide(container);
    unsafe { DeleteAppContainerProfile(name.as_ptr()) };
    std::fs::remove_file(file).ok();
}

/// Removes what any run the application didn't see end left in place, as
/// after a crash: called at launch, when no run is under way.
pub fn cleanup_left() {
    let Ok(entries) = std::fs::read_dir(ledgers()) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().is_some_and(|ext| ext == "jsonl")
            && let Some(container) = path.file_stem().and_then(|stem| stem.to_str())
        {
            cleanup(container);
        }
    }
}

/// Quotes `arg` for a Windows command line.
fn quoted(arg: &OsStr) -> String {
    let arg = arg.to_string_lossy();
    if !arg.is_empty() && !arg.contains([' ', '\t', '"']) {
        return arg.into_owned();
    }
    let mut out = String::from('"');
    let mut slashes = 0;
    for c in arg.chars() {
        match c {
            '\\' => slashes += 1,
            '"' => {
                out.push_str(&"\\".repeat(slashes * 2 + 1));
                out.push('"');
                slashes = 0;
            }
            c => {
                out.push_str(&"\\".repeat(slashes));
                out.push(c);
                slashes = 0;
            }
        }
    }
    out.push_str(&"\\".repeat(slashes * 2));
    out.push('"');
    out
}

/// The launcher: `suspense --sandbox-launch <spec> -- <program> <args>…`.
/// Makes the run's AppContainer and grants, runs the program in it, in a job
/// of its own, waits for it, and takes everything away again. Gives its
/// exit status.
pub fn launch(args: &[String]) -> i32 {
    match launched(args) {
        Ok(code) => code as i32,
        Err(refused) => {
            eprintln!("{}", refused);
            1
        }
    }
}

fn launched(args: &[String]) -> Result<u32, Refused> {
    let (Some(spec), Some(rest)) = (args.first(), args.get(1..)) else {
        return Err(failed("the launch was given nothing to run"));
    };
    let program: Vec<&String> = rest.iter().skip_while(|arg| *arg == "--").collect();
    if program.is_empty() {
        return Err(failed("the launch was given nothing to run"));
    }
    status()?;
    let spec: LaunchSpec = std::fs::read_to_string(spec)
        .ok()
        .and_then(|text| serde_json::from_str(&text).ok())
        .ok_or_else(|| failed("the run's launch couldn't be read"))?;
    std::fs::remove_file(args[0].as_str()).ok();
    let result = run_contained(&spec, &program);
    cleanup(&spec.container);
    result
}

fn run_contained(spec: &LaunchSpec, program: &[&String]) -> Result<u32, Refused> {
    // The run's own identity.
    let name = wide(&spec.container);
    let mut sid: PSID = std::ptr::null_mut();
    let made = unsafe {
        CreateAppContainerProfile(
            name.as_ptr(),
            name.as_ptr(),
            name.as_ptr(),
            std::ptr::null(),
            0,
            &mut sid,
        )
    };
    if made == ALREADY_EXISTS {
        if unsafe { DeriveAppContainerSidFromAppContainerName(name.as_ptr(), &mut sid) } < 0 {
            return Err(failed("the run's AppContainer couldn't be found"));
        }
    } else if made < 0 {
        return Err(Refused {
            message: "the run's AppContainer couldn't be made".into(),
            details: format!("HRESULT {made:#x}"),
        });
    }
    let sid_text = sid_string(sid).ok_or_else(|| failed("the run's identity couldn't be read"))?;
    // Each grant recorded first, so it is always taken away again.
    std::fs::create_dir_all(&spec.ledger.parent().unwrap_or(Path::new("."))).ok();
    for (path, write) in &spec.grants {
        let line = serde_json::to_string(&Granted {
            path: path.clone(),
            sid: sid_text.clone(),
        })
        .unwrap_or_default();
        use std::io::Write as _;
        std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&spec.ledger)
            .and_then(|mut ledger| writeln!(ledger, "{line}"))
            .map_err(|err| Refused {
                message: "a grant couldn't be recorded, so it isn't made".into(),
                details: err.to_string(),
            })?;
        set_access(path, &sid_text, Some(*write))?;
    }
    // Only internetClient, so the harness can reach its model service.
    let mut capability = [0u8; 68];
    let mut size = capability.len() as u32;
    if unsafe {
        CreateWellKnownSid(
            WinCapabilityInternetClientSid,
            std::ptr::null_mut(),
            capability.as_mut_ptr().cast(),
            &mut size,
        )
    } == 0
    {
        return Err(failed("the internetClient capability couldn't be given"));
    }
    let mut capabilities = [SID_AND_ATTRIBUTES {
        Sid: capability.as_mut_ptr().cast(),
        Attributes: SE_GROUP_ENABLED as u32,
    }];
    let security = SECURITY_CAPABILITIES {
        AppContainerSid: sid,
        Capabilities: capabilities.as_mut_ptr(),
        CapabilityCount: 1,
        Reserved: 0,
    };
    // Its standard handles, the only ones it inherits.
    let handles: [HANDLE; 3] = unsafe {
        [
            GetStdHandle(STD_INPUT_HANDLE),
            GetStdHandle(STD_OUTPUT_HANDLE),
            GetStdHandle(STD_ERROR_HANDLE),
        ]
    };
    for handle in handles {
        if handle.is_null() || handle == INVALID_HANDLE_VALUE {
            return Err(failed("the run has no standard handles to give the harness"));
        }
        unsafe { SetHandleInformation(handle, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT) };
    }
    let mut list_size = 0usize;
    unsafe { InitializeProcThreadAttributeList(std::ptr::null_mut(), 2, 0, &mut list_size) };
    let mut list_buffer = vec![0u8; list_size];
    let list: LPPROC_THREAD_ATTRIBUTE_LIST = list_buffer.as_mut_ptr().cast();
    if unsafe { InitializeProcThreadAttributeList(list, 2, 0, &mut list_size) } == 0 {
        return Err(failed("the harness's start couldn't be set up"));
    }
    let updated = unsafe {
        UpdateProcThreadAttribute(
            list,
            0,
            PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES as usize,
            (&security as *const SECURITY_CAPABILITIES).cast(),
            std::mem::size_of::<SECURITY_CAPABILITIES>(),
            std::ptr::null_mut(),
            std::ptr::null(),
        ) != 0
            && UpdateProcThreadAttribute(
                list,
                0,
                PROC_THREAD_ATTRIBUTE_HANDLE_LIST as usize,
                handles.as_ptr().cast(),
                std::mem::size_of_val(&handles),
                std::ptr::null_mut(),
                std::ptr::null(),
            ) != 0
    };
    if !updated {
        unsafe { DeleteProcThreadAttributeList(list) };
        return Err(failed("the harness couldn't be given its AppContainer"));
    }
    let mut startup: STARTUPINFOEXW = unsafe { std::mem::zeroed() };
    startup.StartupInfo.cb = std::mem::size_of::<STARTUPINFOEXW>() as u32;
    startup.StartupInfo.dwFlags = STARTF_USESTDHANDLES;
    startup.StartupInfo.hStdInput = handles[0];
    startup.StartupInfo.hStdOutput = handles[1];
    startup.StartupInfo.hStdError = handles[2];
    startup.lpAttributeList = list;
    // A batch file, as npm installs a harness, runs through cmd.
    let first = PathBuf::from(program[0].as_str());
    let resolved = crate::programs::find(program[0]).unwrap_or(first);
    let batch = resolved
        .extension()
        .is_some_and(|ext| ext.eq_ignore_ascii_case("cmd") || ext.eq_ignore_ascii_case("bat"));
    let mut line: Vec<String> = Vec::new();
    if batch {
        line.extend(["cmd.exe".to_string(), "/d".into(), "/c".into()]);
    }
    line.push(quoted(resolved.as_os_str()));
    line.extend(program[1..].iter().map(|arg| quoted(OsStr::new(arg.as_str()))));
    let mut command_line = wide(line.join(" "));
    let mut info: PROCESS_INFORMATION = unsafe { std::mem::zeroed() };
    let created = unsafe {
        CreateProcessW(
            std::ptr::null(),
            command_line.as_mut_ptr(),
            std::ptr::null(),
            std::ptr::null(),
            1,
            EXTENDED_STARTUPINFO_PRESENT | CREATE_SUSPENDED | CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT,
            std::ptr::null(),
            std::ptr::null(),
            &startup.StartupInfo,
            &mut info,
        )
    };
    unsafe { DeleteProcThreadAttributeList(list) };
    if created == 0 {
        return Err(failed(format!("{} couldn't be started in its AppContainer", program[0])));
    }
    // A job of its own, ending everything with it, which nothing leaves.
    let job = unsafe { CreateJobObjectW(std::ptr::null(), std::ptr::null()) };
    let mut limits: JOBOBJECT_EXTENDED_LIMIT_INFORMATION = unsafe { std::mem::zeroed() };
    limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
    let jailed = !job.is_null()
        && unsafe {
            SetInformationJobObject(
                job,
                JobObjectExtendedLimitInformation,
                (&limits as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),
                std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
            ) != 0
                && AssignProcessToJobObject(job, info.hProcess) != 0
        };
    if !jailed {
        unsafe {
            windows_sys::Win32::System::Threading::TerminateProcess(info.hProcess, 1);
            CloseHandle(info.hThread);
            CloseHandle(info.hProcess);
            if !job.is_null() {
                CloseHandle(job);
            }
        }
        return Err(failed("the harness couldn't be put in its job"));
    }
    unsafe { ResumeThread(info.hThread) };
    unsafe { WaitForSingleObject(info.hProcess, INFINITE) };
    let mut code = 1u32;
    unsafe {
        GetExitCodeProcess(info.hProcess, &mut code);
        CloseHandle(info.hThread);
        CloseHandle(info.hProcess);
        // Ends whatever it left running.
        CloseHandle(job);
    }
    Ok(code)
}

/// A named pipe instance for the piton channel at `name`, open only to the
/// run's AppContainer, by `container`, and the user.
pub fn pipe(name: &str, container: &str) -> std::io::Result<std::fs::File> {
    use std::os::windows::io::FromRawHandle as _;
    let (Some(run), Some(user)) = (container_sid(container), user_sid()) else {
        return Err(std::io::Error::other("the pipe's owners couldn't be named"));
    };
    let sddl = wide(format!("D:P(A;;GA;;;{run})(A;;GA;;;{user})"));
    let mut descriptor: PSECURITY_DESCRIPTOR = std::ptr::null_mut();
    if unsafe {
        ConvertStringSecurityDescriptorToSecurityDescriptorW(
            sddl.as_ptr(),
            SDDL_REVISION_1,
            &mut descriptor,
            std::ptr::null_mut(),
        )
    } == 0
    {
        return Err(std::io::Error::last_os_error());
    }
    let attributes = SECURITY_ATTRIBUTES {
        nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
        lpSecurityDescriptor: descriptor,
        bInheritHandle: 0,
    };
    let name = wide(name);
    let handle = unsafe {
        CreateNamedPipeW(
            name.as_ptr(),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT | PIPE_REJECT_REMOTE_CLIENTS,
            PIPE_UNLIMITED_INSTANCES,
            64 * 1024,
            64 * 1024,
            0,
            &attributes,
        )
    };
    unsafe { LocalFree(descriptor) };
    if handle == INVALID_HANDLE_VALUE {
        return Err(std::io::Error::last_os_error());
    }
    // Waits for the shim; one already connected is connected.
    let connected = unsafe { ConnectNamedPipe(handle, std::ptr::null_mut()) } != 0
        || unsafe { GetLastError() } == windows_sys::Win32::Foundation::ERROR_PIPE_CONNECTED;
    if !connected {
        let err = std::io::Error::last_os_error();
        unsafe { CloseHandle(handle) };
        return Err(err);
    }
    Ok(unsafe { std::fs::File::from_raw_handle(handle as _) })
}

tool_use_result.originalFile:
//! The Windows backend. The SandboxScope's backend is AppContainer, with
//! each run's paths granted to the container's identity in their access
//! lists and the run held in a job object. That backend isn't built yet,
//! so on Windows every run that needs a sandbox fails closed, saying so,
//! and is never started unrestricted, as SANDBOX.md says.

use std::process::Command;

use super::{Compiled, Refused};

fn not_built() -> Refused {
    Refused {
        message: "the Windows sandbox backend (AppContainer) isn't built yet, so no task or \
                  question can run on Windows; runs are never started unrestricted"
            .into(),
        details: format!("See {}", super::DOCUMENTATION),
    }
}

pub fn status() -> Result<String, Refused> {
    Err(not_built())
}

pub fn enforce(_: &mut Command, _: &Compiled) -> Result<(), Refused> {
    Err(not_built())
}

content.content:
//! The controlled piton command, as the SandboxScope's piton says: `piton`
//! on a run's PATH is a small shim, the application's own program run as
//! `suspense --piton-shim`, which asks the application, over a Unix socket
//! in the run's temporary directory made for that run alone, to run the
//! piton command for it, on the host, as trusted work, and streams back what
//! it prints and its exit status. Only what the run's profile allows is run.
//!
//! The protocol: the shim writes its arguments as a JSON array and a line
//! break; the application answers with frames, a tag byte, `o` for standard
//! output, `e` for standard error, then a four-byte big-endian length and
//! the bytes; and last `x` with a four-byte big-endian exit status.

use std::io::{BufRead as _, BufReader, Read as _, Write as _};
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result};

use super::ProfileKind;

/// The environment variable the shim finds its channel by.
pub const SOCKET_ENV: &str = "SUSPENSE_PITON_CHANNEL";

/// The argument the application is run with to be the shim.
pub const SHIM_ARG: &str = "--piton-shim";

/// Whether a run under `kind` may run piton with `args`: a Spec run may
/// build, check, format, and slice; a Code or Question run may only slice
/// with an adapter, which prints compiled output, never the source.
pub fn allowed(kind: ProfileKind, args: &[String]) -> Result<(), String> {
    let command = args.iter().find(|arg| !arg.starts_with('-')).map(String::as_str);
    let adapter = args
        .iter()
        .any(|arg| arg == "--adapter" || arg.starts_with("--adapter="));
    let ok = match kind {
        ProfileKind::Spec | ProfileKind::Freeform => {
            matches!(command, Some("build" | "check" | "fmt" | "format" | "slice"))
                || args.iter().any(|arg| arg == "--version" || arg == "--help")
        }
        ProfileKind::Code | ProfileKind::Question => {
            (command == Some("slice") && adapter)
                || args.iter().any(|arg| arg == "--version" || arg == "--help")
        }
        ProfileKind::Bare => false,
    };
    if ok {
        Ok(())
    } else {
        Err(format!(
            "piton {} isn't allowed in a {} run's sandbox: {}\n",
            args.join(" "),
            kind.label(),
            match kind {
                ProfileKind::Code | ProfileKind::Question =>
                    "only `piton slice --adapter <adapter> <target>` is, which prints compiled output",
                _ => "only build, check, fmt, and slice are",
            }
        ))
    }
}

/// A run's piton channel, listening until it is dropped.
pub struct Server {
    address: PathBuf,
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

impl Server {
    /// Listens for the run of `kind` in the project at `project_dir`, in its
    /// temporary directory `temp`; with the folder holding its `piton` shim,
    /// to put first on its PATH.
    #[cfg(unix)]
    pub fn start(kind: ProfileKind, project_dir: &Path, temp: &Path) -> Result<(Self, PathBuf)> {
        use std::os::unix::net::UnixListener;
        let address = temp.join("piton.sock");
        let listener = UnixListener::bind(&address).context("could not listen for piton")?;
        let bin = temp.join("bin");
        std::fs::create_dir_all(&bin)?;
        let exe = std::env::current_exe().context("could not find the application")?;
        let shim = bin.join("piton");
        let quoted = exe.to_string_lossy().replace('\'', "'\\''");
        std::fs::write(&shim, format!("#!/bin/sh\nexec '{quoted}' {SHIM_ARG} \"$@\"\n"))?;
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(&shim, std::fs::Permissions::from_mode(0o755))?;
        }
        let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let project_dir = project_dir.to_path_buf();
        std::thread::spawn({
            let stop = stop.clone();
            move || {
                for stream in listener.incoming() {
                    if stop.load(std::sync::atomic::Ordering::SeqCst) {
                        break;
                    }
                    let Ok(stream) = stream else {
                        continue;
                    };
                    let project_dir = project_dir.clone();
                    std::thread::spawn(move || serve(kind, &project_dir, stream));
                }
            }
        });
        Ok((Self { address, stop }, bin))
    }

    #[cfg(not(unix))]
    pub fn start(_: ProfileKind, _: &Path, _: &Path) -> Result<(Self, PathBuf)> {
        anyhow::bail!("the piton channel needs a named pipe, which isn't built yet on Windows")
    }

    pub fn address(&self) -> &Path {
        &self.address
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        self.stop.store(true, std::sync::atomic::Ordering::SeqCst);
        // Wakes the listener, so it sees it is to stop.
        #[cfg(unix)]
        std::os::unix::net::UnixStream::connect(&self.address).ok();
        std::fs::remove_file(&self.address).ok();
    }
}

fn frame(out: &mut impl std::io::Write, tag: u8, bytes: &[u8]) -> std::io::Result<()> {
    out.write_all(&[tag])?;
    out.write_all(&(bytes.len() as u32).to_be_bytes())?;
    out.write_all(bytes)
}

/// Answers one request: refused, or run on the host, its output streamed.
#[cfg(unix)]
fn serve(kind: ProfileKind, project_dir: &Path, stream: std::os::unix::net::UnixStream) {
    let mut reader = BufReader::new(match stream.try_clone() {
        Ok(stream) => stream,
        Err(_) => return,
    });
    let mut writer = stream;
    let mut line = String::new();
    if reader.read_line(&mut line).is_err() {
        return;
    }
    let args: Vec<String> = serde_json::from_str(line.trim()).unwrap_or_default();
    if let Err(why) = allowed(kind, &args) {
        frame(&mut writer, b'e', why.as_bytes()).ok();
        frame(&mut writer, b'x', &2i32.to_be_bytes()[..]).ok();
        return;
    }
    crate::debug_log::log(Some(project_dir), format!("piton {} for a {} run", args.join(" "), kind.label()));
    let child = crate::process::command("piton")
        .args(&args)
        .current_dir(project_dir)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn();
    let mut child = match child {
        Ok(child) => child,
        Err(err) => {
            frame(&mut writer, b'e', format!("piton couldn't be run: {err}\n").as_bytes()).ok();
            frame(&mut writer, b'x', &127i32.to_be_bytes()[..]).ok();
            return;
        }
    };
    let (tx, rx) = std::sync::mpsc::channel::<(u8, Vec<u8>)>();
    let pump = |mut from: Box<dyn std::io::Read + Send>, tag: u8, tx: std::sync::mpsc::Sender<(u8, Vec<u8>)>| {
        std::thread::spawn(move || {
            let mut buffer = [0u8; 8192];
            while let Ok(read) = from.read(&mut buffer) {
                if read == 0 {
                    break;
                }
                tx.send((tag, buffer[..read].to_vec())).ok();
            }
        })
    };
    let out = child.stdout.take().map(|out| pump(Box::new(out), b'o', tx.clone()));
    let err = child.stderr.take().map(|err| pump(Box::new(err), b'e', tx.clone()));
    drop(tx);
    for (tag, bytes) in rx {
        if frame(&mut writer, tag, &bytes).is_err() {
            child.kill().ok();
            break;
        }
    }
    out.map(|out| out.join());
    err.map(|err| err.join());
    let code = child.wait().ok().and_then(|status| status.code()).unwrap_or(1);
    frame(&mut writer, b'x', &code.to_be_bytes()[..]).ok();
}

/// The shim: asks the application to run piton with `args`, printing what
/// it prints, and gives its exit status.
pub fn shim(args: Vec<String>) -> i32 {
    #[cfg(unix)]
    {
        let Some(address) = std::env::var_os(SOCKET_ENV) else {
            eprintln!("piton: this run has no piton channel");
            return 127;
        };
        let mut stream = match std::os::unix::net::UnixStream::connect(&address) {
            Ok(stream) => stream,
            Err(err) => {
                eprintln!("piton: couldn't reach the application: {err}");
                return 127;
            }
        };
        let request = serde_json::to_string(&args).unwrap_or_else(|_| "[]".into());
        if stream.write_all(format!("{request}\n").as_bytes()).is_err() {
            return 127;
        }
        let (mut stdout, mut stderr) = (std::io::stdout(), std::io::stderr());
        loop {
            let mut head = [0u8; 5];
            if stream.read_exact(&mut head).is_err() {
                return 1;
            }
            let length = u32::from_be_bytes([head[1], head[2], head[3], head[4]]) as usize;
            let mut body = vec![0u8; length];
            if stream.read_exact(&mut body).is_err() {
                return 1;
            }
            match head[0] {
                b'o' => {
                    stdout.write_all(&body).ok();
                    stdout.flush().ok();
                }
                b'e' => {
                    stderr.write_all(&body).ok();
                }
                b'x' => {
                    return i32::from_be_bytes([body[0], body[1], body[2], body[3]]);
                }
                _ => return 1,
            }
        }
    }
    #[cfg(not(unix))]
    {
        let _ = args;
        eprintln!("piton: the piton channel isn't built on Windows yet");
        127
    }
}
