    #[cfg(windows)]
    let stream = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(&address);
    #[cfg(not(any(unix, windows)))]
    let stream: std::io::Result<std::fs::File> =
        Err(std::io::Error::other("this platform has no piton channel"));
