cat >> src/sandbox/windows.rs <<'EOF'

#[cfg(test)]
mod tests {
    use super::*;

    static RUNS: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

    /// A project with `allowed\note.txt`, granted read-write, beside
    /// `denied\secret.txt`, granted nothing.
    fn project() -> PathBuf {
        let n = RUNS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let root = std::env::temp_dir().join(format!("suspense-windows-test-{}-{n}", std::process::id()));
        std::fs::remove_dir_all(&root).ok();
        std::fs::create_dir_all(root.join("allowed")).unwrap();
        std::fs::create_dir_all(root.join("denied")).unwrap();
        std::fs::write(root.join("allowed").join("note.txt"), "note").unwrap();
        std::fs::write(root.join("denied").join("secret.txt"), "secret").unwrap();
        root
    }

    /// Runs `cmd /d /c <line>` in an AppContainer granted `allowed`, as a
    /// run is, giving its exit status and the container's SID.
    fn contained(root: &Path, line: &str) -> (u32, String) {
        let n = RUNS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let container = format!("Suspense.Test.{}-{n}", std::process::id());
        let spec = LaunchSpec {
            container: container.clone(),
            grants: vec![(root.join("allowed"), true)],
            ledger: ledger(&container),
        };
        let args: Vec<String> = ["cmd.exe", "/d", "/c", line].map(String::from).into();
        let program: Vec<&String> = args.iter().collect();
        let sid = container_sid(&container).unwrap();
        let code = run_contained(&spec, &program).unwrap();
        cleanup(&container);
        (code, sid)
    }

    fn cmd(line: &str) -> bool {
        Command::new("cmd.exe").args(["/d", "/c", line]).status().is_ok_and(|status| status.success())
    }

    #[test]
    fn a_granted_file_is_reached_and_a_denied_one_isnt() {
        let root = project();
        let allowed = root.join("allowed").join("note.txt");
        let denied = root.join("denied").join("secret.txt");
        assert_eq!(contained(&root, &format!("type \"{}\"", allowed.display())).0, 0);
        assert_ne!(contained(&root, &format!("type \"{}\"", denied.display())).0, 0);
        let written = root.join("allowed").join("written.txt");
        assert_eq!(contained(&root, &format!("echo x> \"{}\"", written.display())).0, 0);
        assert_ne!(contained(&root, &format!("echo x> \"{}\"", root.join("denied").join("w.txt").display())).0, 0);
    }

    #[test]
    fn a_junction_or_link_into_the_denied_folder_reaches_nothing() {
        let root = project();
        let junction = root.join("allowed").join("junction");
        assert!(cmd(&format!("mklink /J \"{}\" \"{}\"", junction.display(), root.join("denied").display())));
        assert_ne!(contained(&root, &format!("type \"{}\"", junction.join("secret.txt").display())).0, 0);
        // Symbolic links need developer mode; where they can't be made,
        // there is nothing to follow.
        let link = root.join("allowed").join("link.txt");
        if std::os::windows::fs::symlink_file(root.join("denied").join("secret.txt"), &link).is_ok() {
            assert_ne!(contained(&root, &format!("type \"{}\"", link.display())).0, 0);
        }
    }

    #[test]
    fn a_hard_link_to_a_denied_file_cant_be_made() {
        let root = project();
        let link = root.join("allowed").join("hard.txt");
        let target = root.join("denied").join("secret.txt");
        contained(&root, &format!("mklink /H \"{}\" \"{}\"", link.display(), target.display()));
        assert!(!link.exists());
    }

    #[test]
    fn a_short_name_or_a_stream_of_a_denied_file_reaches_nothing() {
        let root = project();
        let denied = root.join("denied").join("secret.txt");
        std::fs::write(format!("{}:hidden", denied.display()), "stream").unwrap();
        assert_ne!(contained(&root, &format!("more < \"{}:hidden\"", denied.display())).0, 0);
        let long = wide(&denied);
        let mut short = vec![0u16; 1024];
        let length = unsafe {
            windows_sys::Win32::Storage::FileSystem::GetShortPathNameW(
                long.as_ptr(),
                short.as_mut_ptr(),
                short.len() as u32,
            )
        } as usize;
        if length > 0 {
            let short = String::from_utf16_lossy(&short[..length]);
            assert_ne!(contained(&root, &format!("type \"{short}\"")).0, 0);
        }
    }

    #[test]
    fn a_process_outside_the_job_cant_be_reached() {
        let root = project();
        let me = std::process::id();
        assert_ne!(contained(&root, &format!("taskkill /PID {me}")).0, 0);
    }

    #[test]
    fn no_entry_for_the_run_remains_once_it_is_over() {
        let root = project();
        let (_, sid) = contained(&root, "exit 0");
        let listed = Command::new("icacls").arg(root.join("allowed")).arg("/T").output().unwrap();
        assert!(!String::from_utf8_lossy(&listed.stdout).contains(&sid));
    }
}
